```javascript
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  const group = new Group();
  group.position.copy(new Vector3(...(config.scenePosition || [0, 0, 0])));

  // ============================================================================
  // 1. BACKDROP PLANE (stage gradient)
  // ============================================================================
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    color: 0x16161d,
    side: ctx.THREE.FrontSide,
  });
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  backdrop.renderOrder = -1;
  group.add(backdrop);

  // ============================================================================
  // 2. QUOTE PANEL CARD (textured plane)
  // ============================================================================
  const cardWidth = 2.4;
  const cardHeight = 1.5;
  const cardGeom = new PlaneGeometry(cardWidth, cardHeight);

  // Create material with texture
  const cardMat = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
  });

  // Load and assign texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      cardMat.map = texture;
      cardMat.needsUpdate = true;
    });
  }

  const card = new Mesh(cardGeom, cardMat);
  card.position.z = 0.2;
  card.renderOrder = 10;
  group.add(card);

  // ============================================================================
  // 3. ACCENT EDGE (focus indicator, initially hidden)
  // ============================================================================
  const edgeGeom = new PlaneGeometry(
    cardWidth + 0.08,
    cardHeight + 0.08
  );
  const edgeMat = new MeshBasicNodeMaterial({
    color: 0xff2a38,
    transparent: true,
    opacity: 0,
  });
  const edge = new Mesh(edgeGeom, edgeMat);
  edge.position.z = 0.1;
  edge.renderOrder = 9;
  group.add(edge);

  // ============================================================================
  // 4. INTERACTIONS & STATE
  // ============================================================================
  let isHovering = false;
  let hoverTimeline = null;
  let clickTimeline = null;
  let scrollTimeline = null;

  const handlers = {
    onHover: () => {
      if (isHovering) return;
      isHovering = true;

      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.timeline();

      // Subtle rise (0.15 units) with power3.out easing
      hoverTimeline.to(
        card.position,
        {
          z: 0.35,
          duration: 0.5,
          ease: 'power3.out',
        },
        0
      );

      // Accent edge fade in
      hoverTimeline.to(
        edgeMat,
        {
          opacity: 0.7,
          duration: 0.4,
          ease: 'power2.out',
        },
        0
      );
    },

    onUnhover: () => {
      if (!isHovering) return;
      isHovering = false;

      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.timeline();

      // Settle back with overshoot
      hoverTimeline.to(
        card.position,
        {
          z: 0.2,
          duration: 0.6,
          ease: 'power4.out',
        },
        0
      );

      // Accent edge fade out
      hoverTimeline.to(
        edgeMat,
        {
          opacity: 0,
          duration: 0.4,
          ease: 'power2.out',
        },
        0
      );
    },

    onClick: () => {
      if (clickTimeline) clickTimeline.kill();
      clickTimeline = gsap.timeline();

      // Press down: scale 0.97
      clickTimeline.to(
        card.scale,
        {
          x: 0.97,
          y: 0.97,
          duration: 0.12,
          ease: 'back.out',
        },
        0
      );

      // Bounce back to 1
      clickTimeline.to(
        card.scale,
        {
          x: 1,
          y: 1,
          duration: 0.3,
          ease: 'back.out',
        },
        0.12
      );

      // Emit navigation event
      ctx.emit('navigate', { to: 'hub-journal.select' });
    },

    onScroll: (params) => {
      // parallax-scroll handled by ctx.primitives below
    },
  };

  group.userData.handlers = handlers;
  card.userData.interactive = true;
  card.userData.handlers = handlers;

  // ============================================================================
  // 5. CINEMATIC PRIMITIVES
  // ============================================================================
  const primitiveCleanups = [];

  // Apply parallax-scroll
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (prim.name === 'parallax-scroll' && ctx.primitives[prim.name]) {
        const result = ctx.primitives['parallax-scroll'](card, prim.params || {});
        if (result && result.cleanup) {
          primitiveCleanups.push(result.cleanup);
        }
      }
    }
  }

  // ============================================================================
  // 6. CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    if (hoverTimeline) hoverTimeline.kill();
    if (clickTimeline) clickTimeline.kill();
    if (scrollTimeline) scrollTimeline.kill();

    // Clean up primitives
    for (const cleanup of primitiveCleanups) {
      cleanup();
    }

    // Dispose geometry and materials
    backdropGeom.dispose();
    backdropMat.dispose();
    cardGeom.dispose();
    cardMat.dispose();
    edgeGeom.dispose();
    edgeMat.dispose();

    // Dispose textures if loaded
    if (cardMat.map) cardMat.map.dispose();
  };

  return group;
}
